
* {
    box-sizing: border-box;
}

body {
    margin: 0;
    font-family: "Oswald", sans-serif;
    background-image: url("./images/background.png");
    background-size: cover;
    background-position: center center;
    background-repeat: no-repeat;
    background-attachment: fixed;
    min-height: 100vh;
}

header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    padding: 18px 6%;
    border-color: #ffffff;
    border-width: 0 0 1px;
    background: linear-gradient(rgba(10, 10, 10, 0.75), rgba(10, 10, 10, 0.88))
}

h1 {
    margin: 0;
    color: #ffffff;
    font-family: "Oswald", sans-serif;
    font-size: clamp(22px, 4vw, 32px);
    font-weight: 500;
    overflow-wrap: anywhere;
}

button {
    padding: 12px 17px;
    border: 0;
    border-radius: 7px;
    background: #27834b;
    color: white;
    font-family: inherit;
    font-size: 14px;
    cursor: pointer;
    flex-shrink: 0;
}

button:hover {
    background: #206b3d;
}

main {
    width: 100%;
    max-width: 1150px;
    margin: 30px auto;
    padding: 0 22px;
}

#search,
#car-form input {
    display: block;
    width: 100%;
    min-width: 0;
    padding: 13px 14px;
    border: 1px solid #dce2dd;
    border-radius: 7px;
    background: #fff;
    font-family: inherit;
    font-size: 14px;
    outline: none;
}

#search {
    margin-bottom: 22px;
}

#search:focus,
#car-form input:focus {
    border-color: #27834b;
}

#car-form {
    display: block;
    width: 100%;
    min-width: 0;
    margin-bottom: 24px;
    padding: 22px;
    border: 1px solid #e5e9e6;
    border-radius: 10px;
    background: white;
    opacity: 1;
    transform: translateY(0);
    max-height: 700px;
    overflow: hidden;
    transition: opacity 0.3s ease, transform 0.3s ease, max-height 0.4s ease, padding 0.3s ease, margin 0.3s ease;
}

#car-form.is-closed,
#car-form[hidden] {
    display: block;
    opacity: 0;
    transform: translateY(-12px);
    max-height: 0;
    padding-top: 0;
    padding-bottom: 0;
    margin-top: 0;
    margin-bottom: 0;
    border-color: transparent;
    pointer-events: none;
}

#car-form h2 {
    margin: 0 0 18px;
    font-size: clamp(17px, 4vw, 21px);
    overflow-wrap: anywhere;
}

#car-form input {
    margin-bottom: 12px;
}

.cars-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(min(100%, 250px), 1fr));
    gap: 20px;
    align-items: start;
    width: 100%;
    min-width: 0;
}

.car-card {
    width: 100%;
    min-width: 0;
    max-width: 100%;
    overflow: hidden;
    border: 1px solid #e3e8e4;
    border-radius: 10px;
    background: white;
    box-sizing: border-box;
}

.car-card[hidden] {
    display: none;
}

.car-card img {
    display: block;
    width: 100%;
    max-width: 100%;
    height: 180px;
    object-fit: cover;
    background: #edf0ed;
}

.car-content {
    width: 100%;
    min-width: 0;
    max-width: 100%;
    padding: 16px;
    overflow-wrap: anywhere;
}

.car-card h2 {
    min-width: 0;
    max-width: 100%;
    margin: 0 0 5px;
    font-size: clamp(14px, 5vw, 21px);
    line-height: 1.3;
    font-weight: 600;
    overflow-wrap: anywhere;
    word-break: normal;
}

.car-year {
    min-width: 0;
    margin: 0;
    color: #737b75;
    font-size: clamp(12px, 3vw, 14px);
    overflow-wrap: anywhere;
}

.car-specs {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: 10px;
    width: 100%;
    min-width: 0;
    margin-top: 18px;
}

.spec {
    min-width: 0;
    max-width: 100%;
    padding: 10px;
    border-radius: 6px;
    background: #f5f7f5;
    overflow-wrap: anywhere;
}

.spec span {
    display: block;
    min-width: 0;
    margin-bottom: 5px;
    color: #747c76;
    font-size: clamp(10px, 2.5vw, 12px);
    overflow-wrap: anywhere;
}

.spec strong {
    display: block;
    min-width: 0;
    max-width: 100%;
    color: #303832;
    font-size: clamp(11px, 3vw, 14px);
    font-weight: 600;
    overflow-wrap: anywhere;
    word-break: break-word;
}

.car-bottom {
    min-width: 0;
    margin-top: 16px;
    padding-top: 13px;
    border-top: 1px solid #e9ede9;
}

.car-card .price {
    display: block;
    max-width: 100%;
    color: #27834b;
    font-size: clamp(16px, 5vw, 23px);
    font-weight: 700;
    overflow-wrap: anywhere;
    word-break: break-word;
}

.car-enter {
    opacity: 0;
    transform: translateY(12px);
}

.car-enter-active {
    opacity: 1;
    transform: translateY(0);
    transition: opacity 0.35s ease, transform 0.35s ease;
}

@media (max-width: 600px) {
    header {
        padding: 16px;
    }

    main {
        margin-top: 20px;
        padding: 0 14px;
    }

    .cars-grid {
        grid-template-columns: minmax(0, 1fr);
    }

    .car-card img {
        height: 210px;
    }

    #car-form {
        padding: 16px;
    }

    #car-form.is-closed,
    #car-form[hidden] {
        padding-top: 0;
        padding-bottom: 0;
    }
}

@media (prefers-reduced-motion: reduce) {
    .car-enter-active,
    #car-form {
        transition: none;
    }
}

.hero {
    position: relative;
    overflow: hidden;
    padding: 75px 55px;
    margin: 30px auto 55px;
    max-width: 1250px;
    border-radius: 24px;
    background:linear-gradient(90deg, #111827 0%, #111827ee 48%, #11182755 100%), url("data:image/png;base64,") center 55% / cover;
    color: white;
    box-sizing: border-box;
}

.hero-content {
    max-width: 650px;
}

.hero-label,
.section-label {
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 2px;
    color: #f59e0b;
}

.hero h2 {
    margin: 20px 0;
    font-size: clamp(38px, 5vw, 64px);
    line-height: 1.12;
    font-weight: 700;
}

.hero h2 span {
    color: #f59e0b;
}

.hero p {
    max-width: 490px;
    color: #d1d5db;
    font-size: 16px;
    line-height: 1.8;
}

.hero-search {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-top: 30px;
    padding: 8px 18px;
    max-width: 540px;
    min-height: 48px;
    border-radius: 12px;
    background: white;
    color: #111827;
    box-sizing: border-box;
}

.hero-search span {
    font-size: 28px;
}

.hero-search input {
    width: 100%;
    border: none;
    outline: none;
    font-size: 15px;
    background: transparent;
    color: #111827;
}

.hero-buttons {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 20px;
    margin-top: 25px;
}

.hero-button {
    padding: 14px 22px;
    border-radius: 10px;
    background: #f59e0b;
    color: #111827;
    text-decoration: none;
    font-weight: 700;
    transition: background 0.2s, transform 0.2s;
}

.hero-button:hover {
    background: #fbbf24;
    transform: translateY(-2px);
}

.hero-note {
    color: #e5e7eb;
    font-size: 13px;
}

.catalog {
    max-width: 1250px;
    margin: 0 auto 30px;
    padding: 0 20px;
    box-sizing: border-box;
}

.catalog-heading {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 20px;
    margin-bottom: 25px;
}

.catalog-heading h2 {
    margin: 8px 0 0;
    font-size: 30px;
    color: #111827;
}

#add-button {
    border: none;
    border-radius: 10px;
    padding: 14px 20px;
    background: #111827;
    color: white;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s;
}

#add-button:hover {
    background: #374151;
}

.category-list {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 14px;
    margin: 30px 0;
}

.category {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    padding: 15px 23px;
    min-height: 54px;
    background: rgba(10, 15, 22, 0.20);
    color: #f5f5f5;
    border: 1px solid rgba(210, 220, 230, 0.42);
    border-radius: 999px;
    font-family: 'Instrument Sans', sans-serif;
    font-size: 14px;
    font-weight: 600;
    white-space: nowrap;
    cursor: pointer;
    backdrop-filter: blur(8px); 
    -webkit-backdrop-filter: blur(8px);
    transition: background 0.2s ease, color 0.2s ease,border-color 0.2s ease, transform 0.2s ease;
}

.category svg {
    width: 25px;
    height: 25px;
    flex-shrink: 0;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.8;
    stroke-linecap: round;
    stroke-linejoin: round;
}

.category:hover {
    border-color: #ff9914;
    background: rgba(255, 153, 20, 0.13);
    transform: translateY(-2px);
}

.category.active {
    background: #ff9914;
    color: #111827;
    border-color: #ff9914;
}

.category.active:hover {
    background: #ffab35;
    border-color: #ffab35;
}

@media (max-width: 600px) {
    .category-list {
        gap: 9px;
    }

    .category {
        gap: 8px;
        padding: 11px 15px;
        min-height: 46px;
        font-size: 13px;
    }

    .category svg {
        width: 21px;
        height: 21px;
    }
}

/* Страница подробностей автомобиля */
.car-details {
    max-width: 1250px;
    margin: 35px auto 60px;
    padding: 0 20px;
    color: #f5f5f5;
    box-sizing: border-box;
}

.car-details[hidden] {
    display: none !important;
}

.back-button {
    margin-bottom: 25px;
    padding: 12px 18px;
    border: 1px solid rgba(255, 255, 255, 0.25);
    border-radius: 30px;
    background: rgba(17, 24, 39, 0.8);
    color: white;
    font-size: 14px;
    cursor: pointer;
    transition: 0.2s;
}

.back-button:hover {
    background: #ff9914;
    color: #111827;
    border-color: #ff9914;
}

.details-layout {
    display: grid;
    grid-template-columns: 1.3fr 1fr;
    gap: 35px;
    padding: 28px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 24px;
    background: #111827;
    box-sizing: border-box;
}

.details-image {
    min-width: 0;
}

.details-image img {
    display: block;
    width: 100%;
    height: 420px;
    object-fit: cover;
    border-radius: 17px;
    background: #1f2937;
}

.details-info {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}

.details-label {
    color: #ff9914;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 2px;
}

.details-info h1 {
    margin: 16px 0 8px;
    font-size: clamp(28px, 4vw, 42px);
    line-height: 1.15;
}

.details-year {
    margin: 0;
    color: #9ca3af;
    font-size: 16px;
}

.details-price {
    margin: 25px 0;
    color: #ff9914;
    font-size: 34px;
    font-weight: 700;
}

.details-specs {
    width: 100%;
    border-top: 1px solid #374151;
}

.details-spec {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 15px;
    padding: 18px 0;
    border-bottom: 1px solid #374151;
}

.details-spec span {
    color: #9ca3af;
    font-size: 14px;
}

.details-spec strong {
    text-align: right;
    font-size: 14px;
    overflow-wrap: anywhere;
}

.details-action {
    width: 100%;
    margin-top: 25px;
    padding: 15px 20px;
    border: none;
    border-radius: 12px;
    background: #ff9914;
    color: #111827;
    font-size: 15px;
    font-weight: 700;
    cursor: pointer;
    transition: background 0.2s;
}

.details-action:hover {
    background: #ffb13b;
}

/* Адаптация под телефон */
@media (max-width: 800px) {
    .details-layout {
        grid-template-columns: 1fr;
        gap: 25px;
        padding: 18px;
    }

    .details-image img {
        height: 280px;
    }

    .details-price {
        font-size: 29px;
    }
}